export const W=960,H=640;
const ARCHETYPES=[
 {name:'守门人',code:'01 / GATEKEEPER',title:'学习看见空隙',hp:2300,color:'#ff684b',tip:'扇形弹瞄准你发射。等它出手，再横向离开；不要一直贴着边缘。'},
 {name:'万花镜',code:'02 / KALEIDOSCOPE',title:'别追着弹幕跑',hp:2900,color:'#d8b2ff',tip:'螺旋弹之间存在通道。小幅移动，冲刺穿过即将闭合的缝隙。'},
 {name:'赤线核心',code:'03 / THE REDLINE',title:'让每次冲刺都有意义',hp:3600,color:'#ffb85f',tip:'亮起的红色区域是激光预警。提前离开，等光束消失后再回位。'}
];
export const STAGE_COUNT=30;
const STAGE_NAMES=['边界哨站','破晓航道','赤砂要塞','风暴前缘','钢铁防线','折光矩阵','失落港湾','熔火航路','重力裂隙','晨星守望者','暗流入口','断层巡航','深海回声','幽光隧道','黑曜壁垒','逆流火线','静默星环','镜像迷宫','碎星战区','深渊裁决者','终焉前哨','极光封锁','零度风暴','炽核航线','禁区围猎','无尽回廊','天幕坠落','超载矩阵','最后防线','碎甲之心'];
export const BOSSES=STAGE_NAMES.map((name,i)=>{const pattern=i%3,a=ARCHETYPES[pattern],elite=(i+1)%10===0;return {...a,name,code:String(i+1).padStart(2,'0')+' / '+['GATEKEEPER','KALEIDOSCOPE','ARMOR CORE'][pattern],pattern,chapter:Math.floor(i/10),elite,hp:Math.round(a.hp*Math.pow(1+i*.27,1.4)*(elite?1.3:1)),pressure:Math.min(1.65,1+i*.023),color:elite?'#ffd18a':a.color};});
export const xpRequired=level=>60+(level-1)*18+Math.floor(Math.pow(level-1,1.25)*3);
export const combatPace=index=>.65+Math.min(.35,index*.035);
export const droneOffset=i=>({x:(i%2?1:-1)*(43+Math.floor(i/2)*17),y:Math.floor(i/2)*14});
export const MODES={challenge:{label:'标准战役',hp:5,speed:1,density:1,score:1},nightmare:{label:'噩梦协议',hp:3,speed:1.22,density:1.25,score:1.6},practice:{label:'练习飞行',hp:5,speed:.86,density:.88,score:0}};
export const UPGRADES=[
 {id:'pellets',name:'多重弹仓',type:'弹数',icon:'⋮',max:5,desc:'主炮每轮增加 2 枚完整伤害子弹，最多 12 枚。',apply:g=>g.stats.pellets+=2},
 {id:'damage',name:'过载弹芯',type:'伤害',icon:'↗',max:20,desc:'主炮及散射的单发伤害增加 2.8（初始伤害的 20%）。',apply:g=>g.stats.damage+=2.8},
 {id:'rapid',name:'高速扳机',type:'攻速',icon:'»',max:8,desc:'主炮射击间隔缩短 10%，可反复叠加。',apply:g=>g.stats.fireInterval*=.90},
 {id:'spread',name:'分形弹道',type:'武器',icon:'⋔',max:3,desc:'每轮增加两枚斜向弹，各造成主炮 45% 的伤害。',apply:g=>g.stats.sideShots+=2},
 {id:'drone',name:'追猎卫星',type:'武器',icon:'✦',max:4,desc:'增加一架自动发射追踪弹的卫星，伤害随主炮强化成长。',apply:g=>g.stats.drones++},
 {id:'dash',name:'相位跃迁',type:'机动',icon:'ϟ',max:4,desc:'冲刺冷却缩短 18%，冲刺保护延长 0.05 秒。',apply:g=>{g.stats.dashCooldown*=.82;g.stats.dashInvul+=.05;}},
 {id:'armor',name:'复合装甲',type:'生存',icon:'⬡',max:7,desc:'装甲上限增加 1 格，立即修复 2 格。',apply:g=>{g.player.maxHp++;g.player.hp=Math.min(g.player.maxHp,g.player.hp+2);}},
 {id:'reactor',name:'磁暴共振',type:'清屏',icon:'◎',max:6,desc:'清屏伤害增加 120，充能所需擦弹减少 3 次（最低 6 次）。',apply:g=>{g.stats.bombDamage+=120;g.stats.grazeTarget=Math.max(6,g.stats.grazeTarget-3);g.rewardCharge();}},
 {id:'barrier',name:'偏转护盾',type:'生存',icon:'◇',max:2,desc:'每关开始的护盾层数增加 1，立即补充一层。',apply:g=>{g.stats.barrier++;g.player.barrier++;}},
 {id:'repair',name:'战地补给',type:'补给',icon:'+',max:Infinity,fallback:true,desc:'立即修复 2 格装甲，补充 1 发清屏弹。',apply:g=>{g.player.hp=Math.min(g.player.maxHp,g.player.hp+2);g.player.bombs=Math.min(5,g.player.bombs+1);}},
 {id:'recovery',name:'紧急维修',type:'补给',icon:'⬡',max:Infinity,fallback:true,desc:'立即修复 3 格装甲。',apply:g=>g.player.hp=Math.min(g.player.maxHp,g.player.hp+3)},
 {id:'supply',name:'弹药空投',type:'补给',icon:'◎',max:Infinity,fallback:true,desc:'立即补充 2 发清屏弹，最多持有 5 发。',apply:g=>g.player.bombs=Math.min(5,g.player.bombs+2)}
];
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
export function segmentDistance(px,py,ax,ay,bx,by){const dx=bx-ax,dy=by-ay,d=dx*dx+dy*dy,t=d?clamp(((px-ax)*dx+(py-ay)*dy)/d,0,1):0;return Math.hypot(px-ax-dx*t,py-ay-dy*t);}
export function makeRandom(seed=1){let a=seed>>>0;return()=>{a+=0x6D2B79F5;let t=a;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296;};}
export class Game {
 constructor(mode='challenge',startBoss=0,seed=Date.now()){
  this.mode=Object.hasOwn(MODES,mode)?mode:'challenge';this.config=MODES[this.mode];this.random=makeRandom(seed);this.bossIndex=clamp(Math.floor(startBoss)||0,0,STAGE_COUNT-1);this.startBoss=this.bossIndex;this.state='playing';this.time=0;this.stageTime=0;this.score=0;this.grazes=0;this.hits=0;this.deaths=0;this.shots=0;this.damage=0;this.bombsUsed=0;this.dashes=0;this.kills=0;this.events=[];
  this.level=1;this.xp=0;this.totalXP=0;this.upgradeReason=null;this.upgrades={};this.upgradeHistory=[];this.choices=[];this.selectedUpgrade=null;this.stats={damage:14,pellets:2,fireInterval:.105,dashCooldown:2.5,dashInvul:.30,bombDamage:170,grazeTarget:24,sideShots:0,drones:0,barrier:0};this.droneTimer=0;this.labels=[];
  this.player={x:W/2,y:H-85,hp:this.config.hp,maxHp:this.config.hp,invul:2,dash:0,dashCd:0,bombs:3,charge:0,barrier:0,dx:0,dy:-1};this.bullets=[];this.shotsList=[];this.lasers=[];this.particles=[];this.pulses=[];this.enemies=[];this.enemyKills=0;this.escaped=0;this.shotTimer=0;this.fireTimer=0;this.ringTimer=1.4;this.specialTimer=4.2;this.patternTick=0;this.shake=0;this.flash=0;this.message='';this.messageTime=0;this.loadStage(this.bossIndex);
 }
 event(type,extra={}){this.events.push({type,...extra});}
 checkpoint(){return {version:2,mode:this.mode,stage:this.bossIndex,level:this.level,xp:this.xp,totalXP:this.totalXP,upgrades:{...this.upgrades},player:{hp:this.player.hp,bombs:this.player.bombs,charge:this.player.charge},counters:Object.fromEntries(['time','score','grazes','hits','deaths','shots','damage','bombsUsed','dashes','kills','enemyKills','escaped'].map(k=>[k,this[k]]))};}
 static fromCheckpoint(v){if(!v||v.version!==2||!['challenge','nightmare'].includes(v.mode)||!Number.isInteger(v.stage)||v.stage<0||v.stage>=STAGE_COUNT||!Number.isInteger(v.level)||v.level<1||v.level>500||!Number.isInteger(v.xp)||v.xp<0||v.xp>=xpRequired(v.level)||!Number.isInteger(v.totalXP)||v.totalXP<0||!v.upgrades||typeof v.upgrades!=='object'||Array.isArray(v.upgrades)||!v.player||!v.counters)throw Error('存档无效');const g=new Game(v.mode,v.stage);g.upgradeHistory=[];for(const [id,n]of Object.entries(v.upgrades)){const u=UPGRADES.find(x=>x.id===id);if(!u||!Number.isInteger(n)||n<0||n>Math.min(u.max,500))throw Error('强化存档无效');for(let i=0;i<n;i++)u.apply(g);g.upgrades[id]=n;for(let i=0;i<n;i++)g.upgradeHistory.push(id);}for(const key of ['time','score','grazes','hits','deaths','shots','damage','bombsUsed','dashes','kills','enemyKills','escaped']){const n=v.counters[key];if(!Number.isFinite(n)||n<0||n>1e9)throw Error('战役记录无效');g[key]=n;}for(const key of ['hp','bombs','charge'])if(!Number.isInteger(v.player[key])||v.player[key]<0)throw Error('机体状态无效');if(v.player.hp<1||v.player.hp>g.player.maxHp||v.player.bombs>5||v.player.charge>=g.stats.grazeTarget)throw Error('补给状态无效');g.level=v.level;g.xp=v.xp;g.totalXP=v.totalXP;g.loadStage(v.stage);Object.assign(g.player,v.player);g.events=[];return g;}
 loadStage(index){this.bossIndex=index;const b=BOSSES[index];this.boss={x:W/2,y:112,hp:b.hp,maxHp:b.hp,phase:0,shield:1.7,clock:0,flash:0};this.stageTime=0;this.spawnSerial=0;this.fireTimer=.9;this.ringTimer=2;this.specialTimer=4;this.patternTick=0;this.bullets=[];this.shotsList=[];this.lasers=[];this.enemies=[];this.shotTimer=0;this.droneTimer=0;this.player.x=W/2;this.player.y=H-85;this.player.invul=2;this.player.dash=0;this.player.dashCd=0;this.player.barrier=this.stats.barrier;this.encounter=this.mode==='practice'?'boss':'waves';this.wave=1;this.waveTime=0;this.spawnTimer=1.5;this.spawnRemaining=this.waveQuota();this.warningTime=0;this.announce(this.mode==='practice'?b.name+' / 链路接入':'第 '+(index+1)+' 关 / 敌方机群接近',2.5);this.event(this.mode==='practice'?'boss':'wave',{index,wave:1});}
 waveQuota(){return 12+this.wave*3+Math.floor(this.bossIndex*.65);}
 spawnEnemy(){const serial=this.spawnSerial||0;this.spawnSerial=serial+1;const kind=this.wave===1?'scout':this.wave===2?(serial%3===0?'striker':'scout'):(serial%4===0?'carrier':serial%2?'striker':'scout'),lane=[1,5,3,0,6,2,4][(serial+this.wave-1)%7],x=90+lane*130,scale=1+this.bossIndex*.14+Math.pow(this.bossIndex,1.5)*.012,hp=Math.round((kind==='scout'?42:kind==='striker'?70:120)*scale),xp=(kind==='scout'?6:kind==='striker'?10:16)*(1+Math.floor(this.bossIndex/10));this.enemies.push({x,y:-35-(serial%2)*22,baseX:x,kind,r:kind==='carrier'?24:kind==='striker'?19:15,hp,maxHp:hp,xp,age:0,phase:(serial%4)*Math.PI/2,volley:0,fire:2.4+(serial%4)*.45,flash:0});}
 hurtEnemy(enemy,damage){if(enemy.dead||this.state!=='playing')return;const dealt=Math.min(enemy.hp,damage);enemy.hp-=dealt;enemy.flash=.08;this.damage+=dealt;this.score+=Math.round(dealt*2*this.config.score);if(enemy.hp<=0){enemy.dead=true;this.enemyKills++;this.score+=Math.round(160*this.config.score);const xp=enemy.xp||6;this.xp+=xp;this.totalXP+=xp;this.labels.push({x:enemy.x,y:enemy.y,text:'+'+xp+' XP',age:0});this.pulses.push({x:enemy.x,y:enemy.y,r:0,age:.43});for(let i=0;i<7;i++){const a=i*Math.PI*2/7;this.particles.push({x:enemy.x,y:enemy.y,vx:Math.cos(a)*90,vy:Math.sin(a)*90,age:0,kind:'debris'});}this.event('enemyDown');}}
 checkLevel(){if(this.state!=='playing'||this.xp<xpRequired(this.level))return false;this.xp-=xpRequired(this.level);this.level++;this.state='upgrade';this.offerUpgrades('level');this.event('levelup',{level:this.level});return true;}
 beginBoss(){if(this.state!=='playing'||this.encounter!=='waves'||this.wave<3||this.spawnRemaining>0||this.enemies.some(e=>!e.dead))return false;this.encounter='warning';this.warningTime=2.5;this.bullets=[];this.shotsList=[];this.enemies=[];this.player.invul=Math.max(this.player.invul,2.6);this.announce('WARNING / 大型敌机正在接近',2.5);this.event('bossIncoming');return true;}
 waveCombat(dt){this.waveTime+=dt;this.spawnTimer-=dt;const cap=this.bossIndex<5?8+Math.floor(this.bossIndex/3):Math.min(20,12+Math.floor((this.bossIndex-5)/3));if(this.spawnRemaining>0&&this.spawnTimer<=0&&this.enemies.length<cap){const batch=Math.min(this.spawnRemaining,this.bossIndex<10?2:3,cap-this.enemies.length);for(let n=0;n<batch;n++){this.spawnEnemy();this.spawnRemaining--;}this.spawnTimer=Math.max(.8,1.1-this.bossIndex*.008)/this.config.density;}
  for(const e of this.enemies){e.age+=dt;e.flash=Math.max(0,e.flash-dt);const speed=e.kind==='scout'?52:e.kind==='striker'?35:27;e.y+=(e.age>11?85:speed)*dt*this.config.speed;e.x=clamp(e.baseX+Math.sin(e.age*.75+e.phase)*(e.kind==='carrier'?18:28),30,W-30);e.fire-=dt;if(e.y>70&&e.y<H-200&&e.fire<=0){const early=this.bossIndex<5;let a=Math.PI/2;if(this.bossIndex>=10&&e.kind==='striker'&&e.volley%2===1)a=clamp(Math.atan2(this.player.y-e.y,this.player.x-e.x),Math.PI/2-.45,Math.PI/2+.45);const count=e.kind==='carrier'?(this.bossIndex<10?3:5):e.kind==='striker'?3:1;for(let i=0;i<count;i++)this.bullet(e.x,e.y+12,a+(i-(count-1)/2)*.28,78+Math.min(52,this.bossIndex*1.8),5,e.kind==='carrier'?1:0);e.volley++;e.fire=(e.kind==='scout'?(early?4.0:3.2):e.kind==='striker'?(early?4.8:3.6):(early?5.2:4.0))/(this.config.density*Math.min(1.15,1+this.bossIndex*.006));}if(e.y>H+50){e.dead=true;this.escaped++;}}
  this.enemies=this.enemies.filter(e=>!e.dead);if(this.spawnRemaining===0&&this.enemies.length===0){if(this.wave<3){this.wave++;this.waveTime=0;this.spawnRemaining=this.waveQuota();this.spawnTimer=1.0;this.announce('清扫 '+this.wave+' / 3 · '+['','侦察编队','突击编队','重装编队'][this.wave],1.8);this.event('wave',{wave:this.wave});}else this.beginBoss();}}
 offerUpgrades(reason='clear'){const pool=UPGRADES.filter(u=>!u.fallback&&(this.upgrades[u.id]||0)<u.max);for(let i=pool.length-1;i>0;i--){const j=Math.floor(this.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]];}const core=pool.find(u=>['pellets','damage','rapid'].includes(u.id));this.choices=(core?[core,...pool.filter(u=>u!==core)]:pool).slice(0,3).map(u=>u.id);for(const u of UPGRADES.filter(u=>u.fallback))if(this.choices.length<3)this.choices.push(u.id);this.selectedUpgrade=null;this.upgradeReason=reason;}
 chooseUpgrade(id){if(!['intermission','upgrade'].includes(this.state)||this.selectedUpgrade||!this.choices.includes(id))return false;const u=UPGRADES.find(u=>u.id===id);if(!u||(this.upgrades[id]||0)>=u.max)return false;const levelChoice=this.state==='upgrade';u.apply(this);this.upgrades[id]=(this.upgrades[id]||0)+1;this.upgradeHistory.push(id);this.selectedUpgrade=id;this.event('upgrade',{id});if(levelChoice){this.state='playing';this.choices=[];this.selectedUpgrade=null;this.upgradeReason=null;this.checkLevel();}return true;}
 rewardCharge(){const p=this.player;while(p.charge>=this.stats.grazeTarget){p.charge-=this.stats.grazeTarget;p.bombs=Math.min(5,p.bombs+1);this.announce('擦弹充能完成 / 清屏弹 +1',1.8);this.event('charge');}}
 announce(message,seconds=2){this.message=message;this.messageTime=seconds;}
 bullet(x,y,angle,speed,r=5,kind=0){const m=this.config.speed*(.78+Math.min(.42,this.bossIndex*.0145));this.bullets.push({x,y,px:x,py:y,vx:Math.cos(angle)*speed*m,vy:Math.sin(angle)*speed*m,r,kind,grazed:false,age:0});}
 ring(count,speed,offset=0,x=this.boss.x,y=this.boss.y,kind=0){for(let i=0;i<count;i++)this.bullet(x,y,offset+i*Math.PI*2/count,speed,kind===1?4:5,kind);}
 fan(count,speed,spread=.16,offset=0){const a=Math.atan2(this.player.y-this.boss.y,this.player.x-this.boss.x)+offset;for(let i=0;i<count;i++)this.bullet(this.boss.x,this.boss.y+22,a+(i-(count-1)/2)*spread,speed,6,0);}
 laser(axis,pos,width=48,delay=.95){this.lasers.push({axis,pos,width,delay,live:.42,age:0});this.event('warning');}
 dash(input={}){const p=this.player;if(this.state!=='playing'||p.dashCd>0)return false;let dx=(input.right?1:0)-(input.left?1:0),dy=(input.down?1:0)-(input.up?1:0);if(input.target){dx=input.target.x-p.x;dy=input.target.y-p.y;}let len=Math.hypot(dx,dy);if(len<.01){dx=p.dx;dy=p.dy;len=1;}p.dx=dx/len;p.dy=dy/len;p.dash=.20;p.dashCd=this.stats.dashCooldown;p.invul=Math.max(p.invul,this.stats.dashInvul);this.dashes++;this.event('dash');return true;}
 bomb(){const p=this.player;if(this.state!=='playing'||this.encounter==='warning'||p.bombs<=0)return false;p.bombs--;this.bombsUsed++;p.invul=Math.max(p.invul,1.2);this.bullets=[];this.lasers=[];this.pulses.push({x:p.x,y:p.y,r:0,age:0});this.shake=.23;this.flash=.22;if(this.encounter==='boss')this.hurtBoss(this.stats.bombDamage);else for(const enemy of this.enemies)this.hurtEnemy(enemy,this.stats.bombDamage);this.event('bomb');this.checkLevel();return true;}
 hurtBoss(amount){if(this.state!=='playing'||this.encounter!=='boss'||this.boss.shield>0)return;const b=this.boss,old=b.hp,threshold=b.maxHp*(2-b.phase)/3;b.hp=Math.max(b.phase<2?threshold:0,b.hp-amount);this.damage+=old-b.hp;this.score+=Math.round((old-b.hp)*3*this.config.score);b.flash=.06;
  if(b.hp<=0){this.kills++;this.score+=Math.round((5000+this.player.hp*500)*this.config.score);this.bullets=[];this.shotsList=[];this.lasers=[];this.shake=.4;this.pulses.push({x:b.x,y:b.y,r:0,age:0});if(this.bossIndex===STAGE_COUNT-1||this.mode==='practice'){this.state='won';this.event('win');}else{this.state='intermission';this.offerUpgrades();this.event('stageClear');}return;}
  if(b.phase<2&&b.hp<=threshold){b.hp=threshold;b.phase++;b.shield=1.35;this.bullets=[];this.lasers=[];this.player.invul=Math.max(this.player.invul,1.4);this.fireTimer=.6;this.ringTimer=1.1;this.specialTimer=2;this.announce('PHASE '+(b.phase+1)+' / 攻击协议升级',2);this.event('phase');}
 }
 nextBoss(){if(this.state!=='intermission'||!this.selectedUpgrade)return false;this.player.hp=Math.min(this.player.maxHp,this.player.hp+1);this.player.bombs=Math.min(5,this.player.bombs+1);this.choices=[];this.selectedUpgrade=null;this.state='playing';this.loadStage(this.bossIndex+1);return true;}
 hit(){const p=this.player;if(p.invul>0||this.state!=='playing')return false;if(p.barrier>0){p.barrier--;p.invul=1.2;this.bullets=this.bullets.filter(b=>Math.hypot(b.x-p.x,b.y-p.y)>70);this.announce('偏转护盾 / 已抵挡一次攻击',1.5);this.event('barrier');return true;}this.hits++;p.hp--;p.invul=1.65;this.shake=.25;this.flash=.1;this.bullets=this.bullets.filter(b=>Math.hypot(b.x-p.x,b.y-p.y)>70);this.event('hit');if(p.hp<=0){if(this.mode==='practice'){this.deaths++;p.hp=p.maxHp;p.invul=3;this.bullets=[];this.lasers=[];this.announce('练习复位 / 继续观察攻击规律',2.5);this.event('respawn');}else{this.state='lost';this.event('lose');}}return true;}
 attacks(dt){const b=this.boss,stage=BOSSES[this.bossIndex],i=stage.pattern,p=b.phase,intro=this.bossIndex<5,d=this.config.density*stage.pressure*combatPace(this.bossIndex);b.clock+=dt;if(b.shield>0)return;this.fireTimer-=dt;this.ringTimer-=dt;this.specialTimer-=dt;
  if(this.fireTimer<=0){this.patternTick++;
   if(i===0){this.fan(intro?3+2*Math.floor(p/2):5+p*2,135+p*16,.23);this.fireTimer=(1.05-p*.16)/d;}
   if(i===1){const a=this.patternTick*(intro?.24:.34),arms=intro?3:4+p;for(let arm=0;arm<arms;arm++)this.bullet(b.x,b.y,a+arm*Math.PI*2/arms,126+p*17,4,1);this.fireTimer=(intro?.24:.15)/d;}
   if(i===2){this.fan(intro?3+p:3+p*2,intro?145+p*10:185+p*12,.20);const a=this.patternTick*.34,arms=intro?2:4;for(let arm=0;arm<arms;arm++)this.bullet(b.x,b.y,a+arm*Math.PI*2/arms,123+p*12,4,1);this.fireTimer=(.75-p*.08)/d;}
  }
  if(this.ringTimer<=0){const a=Math.PI/2+this.patternTick*.12;this.ring(intro?12+p*2:Math.round((i===0?18:22)+p*4+stage.chapter*4),98+i*12+p*15,a,b.x,b.y,1);if((!intro&&i===1&&p>0)||stage.elite)this.ring(18,160,a+.09,b.x,b.y,0);this.ringTimer=(i===0?3.0:i===1?3.7:2.8)/d;}
  if(this.specialTimer<=0){const delay=intro?.45:0;if(i===0){if(p>0)this.laser('x',this.player.x,intro?42:56,1.15+delay);}else if(i===1){this.laser('x',this.player.x,46,1.0+delay);if(!intro&&p===2)this.laser('x',clamp(this.player.x+160,30,W-30),46,1.15);}else{this.laser('x',this.player.x,intro?42:58,.92+delay);if(!intro&&p>0)this.laser('y',this.player.y,42,1.1);if(!intro&&p===2){const lane=(Math.floor(this.stageTime/3)%5)*160+160;this.laser('x',lane,60,1.3);}}this.specialTimer=(i===0?5:i===1?4.3:3.4)/d;}
 }
 update(dt,input={}){
  if(this.state!=='playing')return;dt=clamp(dt,0,.034);this.shake=Math.max(0,this.shake-dt);this.flash=Math.max(0,this.flash-dt);this.messageTime=Math.max(0,this.messageTime-dt);for(const p of this.particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.age+=dt;}this.particles=this.particles.filter(p=>p.age<.5).slice(-180);for(const p of this.pulses){p.age+=dt;p.r+=1400*dt;}this.pulses=this.pulses.filter(p=>p.age<.65);for(const label of this.labels){label.age+=dt;label.y-=25*dt;}this.labels=this.labels.filter(l=>l.age<.8).slice(-40);
  this.time+=dt;this.stageTime+=dt;const p=this.player,b=this.boss;p.invul=Math.max(0,p.invul-dt);p.dashCd=Math.max(0,p.dashCd-dt);b.shield=Math.max(0,b.shield-dt);b.flash=Math.max(0,b.flash-dt);
  let dx=(input.right?1:0)-(input.left?1:0),dy=(input.down?1:0)-(input.up?1:0);if(input.target){dx=input.target.x-p.x;dy=input.target.y-p.y;if(Math.hypot(dx,dy)<4){dx=0;dy=0;}}let len=Math.hypot(dx,dy);if(len){dx/=len;dy/=len;}const oldX=p.x,oldY=p.y;
  if(p.dash>0){p.dash=Math.max(0,p.dash-dt);p.x+=p.dx*960*dt;p.y+=p.dy*960*dt;this.particles.push({x:p.x,y:p.y,vx:0,vy:50,age:0,kind:'trail'});}else{let distance=(input.slow?135:input.target?.touch?800:370)*dt;if(input.target)distance=Math.min(distance,Math.hypot(input.target.x-p.x,input.target.y-p.y));p.x+=dx*distance;p.y+=dy*distance;if(len){p.dx=dx;p.dy=dy;}}
  p.x=clamp(p.x,18,W-18);p.y=clamp(p.y,175,H-20);
  if(this.encounter==='warning'){this.warningTime-=dt;if(this.warningTime<=0){this.encounter='boss';this.stageTime=0;b.shield=1.7;this.player.invul=Math.max(this.player.invul,1.8);this.announce(BOSSES[this.bossIndex].name+' / 决战开始',2);this.event('boss',{index:this.bossIndex});}return;}
  if(this.encounter==='waves')this.waveCombat(dt);if(this.encounter==='warning')return;
  b.x=W/2+Math.sin(this.stageTime*(.46+BOSSES[this.bossIndex].pattern*.1+Math.min(.2,this.bossIndex*.006)))*215;b.y=108+Math.sin(this.stageTime*.9)*15;
  this.shotTimer-=dt;if(input.fire!==false&&this.shotTimer<=0){for(let i=0;i<this.stats.pellets;i++){const offset=(i-(this.stats.pellets-1)/2)*Math.min(10,42/Math.max(1,this.stats.pellets-1));this.shotsList.push({x:p.x+offset,y:p.y-20,py:p.y-20,vx:0,vy:-770,damage:this.stats.damage,kind:'main'});}for(let i=0;i<this.stats.sideShots;i++){const side=i%2?1:-1,rank=Math.floor(i/2)+1;this.shotsList.push({x:p.x+side*17,y:p.y-8,py:p.y-8,vx:side*(115+rank*65),vy:-740,damage:this.stats.damage*.45,kind:'spread'});}this.shotTimer=this.stats.fireInterval;this.shots+=this.stats.pellets+this.stats.sideShots;}
  const foes=()=>this.encounter==='boss'?[b]:this.enemies.filter(e=>!e.dead);const nearest=shot=>foes().reduce((best,e)=>!best||Math.hypot(e.x-shot.x,e.y-shot.y)<Math.hypot(best.x-shot.x,best.y-shot.y)?e:best,null);
  this.droneTimer-=dt;if(this.stats.drones&&this.droneTimer<=0&&foes().length){for(let i=0;i<this.stats.drones;i++){const offset=droneOffset(i);this.shotsList.push({x:p.x+offset.x,y:p.y-6+offset.y,py:p.y-6+offset.y,vx:0,vy:-580,damage:24*(1+(this.stats.damage/14-1)*.6),kind:'drone'});this.shots++;}this.droneTimer=.7;}
  if(this.encounter==='boss')this.attacks(dt);
  for(const shot of this.shotsList){shot.px=shot.x;shot.py=shot.y;if(shot.kind==='drone'){const target=nearest(shot);if(target){const dx=target.x-shot.x,dy=target.y-shot.y,len=Math.hypot(dx,dy)||1;shot.vx=dx/len*580;shot.vy=dy/len*580;}}shot.x+=(shot.vx||0)*dt;shot.y+=shot.vy*dt;if(this.encounter==='boss'&&shot.y>=b.y-37&&shot.y<=b.y+42&&Math.abs(shot.x-b.x)<48&&this.state==='playing'){this.hurtBoss(shot.damage);shot.dead=true;}else if(this.encounter==='waves')for(const enemy of this.enemies){if(!enemy.dead&&segmentDistance(enemy.x,enemy.y,shot.px,shot.py,shot.x,shot.y)<enemy.r+3){this.hurtEnemy(enemy,shot.damage);shot.dead=true;break;}}}
  this.shotsList=this.shotsList.filter(s=>!s.dead&&s.y>-30&&s.y<H+50&&s.x>-40&&s.x<W+40).slice(-800);
  if(this.state!=='playing')return;
  for(const bullet of this.bullets){bullet.px=bullet.x;bullet.py=bullet.y;bullet.x+=bullet.vx*dt;bullet.y+=bullet.vy*dt;bullet.age+=dt;const distance=segmentDistance(p.x,p.y,bullet.px,bullet.py,bullet.x,bullet.y);const moveDistance=segmentDistance(bullet.x,bullet.y,oldX,oldY,p.x,p.y);
   if(Math.min(distance,moveDistance)<bullet.r+4&&p.invul<=0){bullet.dead=true;this.hit();}
   else if(distance<bullet.r+24&&!bullet.grazed&&p.invul<=0){bullet.grazed=true;this.grazes++;this.score+=Math.round(80*this.config.score);p.charge++;this.rewardCharge();this.event('graze');}
  }
  this.bullets=this.bullets.filter(q=>!q.dead&&q.x>-70&&q.x<W+70&&q.y>-100&&q.y<H+70&&q.age<15).slice(-1800);
  for(const enemy of this.enemies)if(!enemy.dead&&Math.hypot(enemy.x-p.x,enemy.y-p.y)<enemy.r+4&&p.invul<=0){this.hit();enemy.dead=true;}this.enemies=this.enemies.filter(e=>!e.dead);
  for(const laser of this.lasers){laser.age+=dt;if(laser.age>=laser.delay&&laser.age<laser.delay+laser.live){const coordinate=laser.axis==='x'?p.x:p.y;if(Math.abs(coordinate-laser.pos)<laser.width/2+4)this.hit();}}
  this.lasers=this.lasers.filter(l=>l.age<l.delay+l.live);
  this.checkLevel();
 }
}
